// @ts-nocheck
/* eslint-disable */
/**
 * LeadCreateDropdowns — the logic of the four dropdowns (product → step group → owner / sales person) of the "create lead" modal.
 * GENERATED by tools/sync-prospects.mjs from web/js/lead/lead_create_dropdowns.js — do not edit; change the script and run `npm run prospects:sync`.
 *
 * The Java script, same behaviour line by line (ES5 written for a browser global scope — hence "@ts-nocheck"). What differs from the original:
 *   - it is a factory (makeLeadCreateDropdowns) instead of window.LeadCreateDropdowns, and its five requests go through the fetch it is given
 *     (Java: window.fetch with the relative address '../board/…'; here ctx + '/board/…' through the injected backend);
 *   - the module is shared: contracts_master_data.xhtml (the prospect form) uses the same script — move it to a shared folder with that page.
 * Original header:
 *
 *    ★ 14/09/2026 — logic กลางของ 4 dropdown (ผลิตภัณฑ์ → กลุ่มขั้นตอน → ผู้รับผิดชอบ/พนักงานขาย)
 *      ใน modal "บันทึกและสร้าง Lead" ใช้ร่วมกันทั้ง contracts_master_data.xhtml (ต้องสร้าง prospect ใหม่ด้วย)
 *      และ contracts.xhtml (มี prospect อยู่แล้ว) — เดิม 2 หน้า copy-paste logic นี้แยกกัน (mdXxx / clXxx)
 *      จนเบี่ยงกันไปเอง (เช่น กรอง "พนักงานขาย" ตามกลุ่มขั้นตอนหรือไม่ — คนละคำตอบ) รวมไว้ที่เดียวกันเพื่อกันเบี่ยงซ้ำ
 *      ส่วน submit/สร้าง lead จริง ๆ ยังแยกกันตามเดิม (คนละ write path โดยจำเป็น) ไม่ได้รวมที่นี่
 *   
 *      ใช้: <script src="../js/lead/lead_create_dropdowns.js"></script> ก่อน inline script ที่เรียก
 *      LeadCreateDropdowns.create({ selectLabel, myEmployeeId, onChange, onStepGroupRequiredChange })
 */

export interface LeadCreateDropdownsDeps {
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** prefix of the BFF paths ('' in this app) */
  ctx?: string;
}

export interface LeadCreateDropdowns {
  create(opts?: Record<string, unknown>): {
    load(): void;
    onProductChange(): void;
    onStepGroupChange(): void;
    setSelect(id: string, val: string): void;
    isStepGroupRequired(): boolean;
  };
}

export function makeLeadCreateDropdowns(deps: LeadCreateDropdownsDeps): LeadCreateDropdowns {
    'use strict';
    var env = { fetch: deps.fetch, ctx: deps.ctx || '' };

    // escape ใช้ได้ทั้งเนื้อความ option และค่าใน attribute (จึงต้องครอบ " ด้วย)
    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }
    function toJson(r) { return r.ok ? r.json() : null; }
    // ป้ายของ 1 รายการ master-data — "รหัส ชื่อ" (nameOnly = เอาแค่ชื่อ) ใช้ให้ตรงกันทุก dropdown
    function labelOf(o, nameOnly) { return (nameOnly || !o.code) ? (o.name || o.id) : (o.code + ' ' + (o.name || '')); }

    var DEFAULT_IDS = { product: 'clProduct', stepGroup: 'clStepGroup', stepGroupStar: 'clStepGroupStar', owner: 'clOwner', sales: 'clSales' };

    function create(opts) {
        opts = opts || {};
        var ids = opts.ids || DEFAULT_IDS;
        var selectLabel = opts.selectLabel || '';
        var myEmployeeId = opts.myEmployeeId || '';
        var onChange = opts.onChange || function () {};
        var onStepGroupRequiredChange = opts.onStepGroupRequiredChange || function () {};

        // ลิสต์เต็มของผู้รับผิดชอบ (ทั้งบริษัท) — เก็บไว้ filter ใหม่ตอนเลือก "กลุ่มขั้นตอน" (onStepGroupChange)
        // และ restore กลับตอนล้างกลุ่ม (พนักงานขายไม่ผูกกับกลุ่มแล้ว จึงไม่ต้องเก็บลิสต์เต็มไว้กรอง)
        var ALL_OWNERS = [];
        var NO_LINE = '__none__';
        var noneLabel = opts.noneLabel || 'ไม่ระบุ';
        var OPTIONS_CALL = null;
        function optionSets() {
            if (!OPTIONS_CALL) {
                OPTIONS_CALL = env.fetch(env.ctx + '/board/prospect-options?sets=salesLines,responsibles,waitlists,salePersons', { credentials: 'same-origin' }).then(toJson).catch(function () { return null; });
            }
            return OPTIONS_CALL;
        }
        var LINE_OWNERS_FOR = '';
        function setOwners(list) { fill(ids.owner, list, true); defaultSalesFromOwner(); }
        function restoreOwners() { LINE_OWNERS_FOR = ''; setOwners(ALL_OWNERS); }
        function loadOwnersOfLine(lineId) {
            LINE_OWNERS_FOR = lineId;
            env.fetch(env.ctx + '/board/prospect-options?sets=responsibles&salesLineId=' + encodeURIComponent(lineId), { credentials: 'same-origin' }).then(toJson).catch(function () { return null; })
                .then(function (o) {
                    if (LINE_OWNERS_FOR !== lineId) { return; }
                    if (o && o.responsibles) { setOwners(o.responsibles); }
                });
        }
        function withNone(lines) { return [{ id: NO_LINE, name: noneLabel }].concat(lines || []); }
        function ownersOf(o) {
            return (o.waitlists || []).map(function (w) { return { id: 'wl:' + w.id, name: w.name || w.id }; }).concat(o.responsibles || []);
        }
        var stepGroupRequired = true;

        function fill(id, items, nameOnly) {
            var sel = document.getElementById(id); if (!sel) return;
            var h = '<option value="">' + selectLabel + '</option>';
            (items || []).forEach(function (o) {
                var label = labelOf(o, nameOnly);
                // ผลิตภัณฑ์พ่วง usesWorkflowStep มาด้วย — ใช้ตัดสินว่าต้องเลือกกลุ่มขั้นตอนไหม
                var wf = (o.usesWorkflowStep != null) ? (' data-wf="' + (o.usesWorkflowStep ? '1' : '0') + '"') : '';
                // พนักงานขายพ่วง object employee มาด้วย — เก็บ id/ป้ายไว้เติม "ผู้รับผิดชอบ" อัตโนมัติ
                var empId = o.employeeId || (o.employee && o.employee.id) || '';
                var emp = empId ? (' data-emp="' + empId + '" data-emp-label="' + esc(o.employee ? labelOf(o.employee, true) : '') + '"') : '';
                h += '<option value="' + o.id + '"' + wf + emp + '>' + esc(label) + '</option>';
            });
            sel.innerHTML = h;
        }

        // ตั้งค่า select แบบ programmatic + สะกิดให้ open_down_select (ODS) รีเฟรชป้ายปุ่ม
        // (ODS observe childList — set value เฉย ๆ ป้ายปุ่มไม่อัปเดต)
        function setSelect(id, val) {
            var s = document.getElementById(id); if (!s) return;
            s.value = val;
            var c = document.createComment('ods'); s.appendChild(c); s.removeChild(c);
            s.dispatchEvent(new Event('change', { bubbles: true }));
        }

        // ตั้งว่า "กลุ่มขั้นตอน" บังคับเลือกไหม — ช่องยังแสดงตลอด ซ่อนแค่เครื่องหมาย * ตอนไม่บังคับ
        function setStepGroupRequired(required) {
            stepGroupRequired = !!required;
            var star = document.getElementById(ids.stepGroupStar);
            if (star) { star.style.display = stepGroupRequired ? '' : 'none'; }
            onStepGroupRequiredChange(stepGroupRequired);
        }

        // เลือก/เปลี่ยน "ผู้รับผิดชอบ" → หาพนักงานขายที่ employee.id (data-emp) ตรงกับ id ผู้รับผิดชอบ
        // เจอ → auto ทับค่าพนักงานขายเสมอ ไม่ว่าก่อนหน้านี้จะว่างหรือเลือกไว้แล้วก็ตาม
        // ไม่เจอ → ปล่อยค่าพนักงานขายเดิมไว้เฉยๆ (ว่างอยู่แล้วก็ว่างต่อ / เลือกไว้แล้วก็ไม่ทับ ไม่เคลียร์)
        // ทางกลับกัน: แก้ "พนักงานขาย" เองทีหลัง ไม่มี listener ย้อนกลับไปเปลี่ยนผู้รับผิดชอบหรือ field อื่น
        function defaultSalesFromOwner() {
            var owner = (document.getElementById(ids.owner) || {}).value || '';
            var sales = document.getElementById(ids.sales);
            if (!owner || !sales) { return; }
            for (var i = 0; i < sales.options.length; i++) {
                if (sales.options[i].getAttribute('data-emp') === owner) {
                    setSelect(ids.sales, sales.options[i].value);
                    return;
                }
            }
        }

        function load() {
            OPTIONS_CALL = null;   // every opening asks again (the backend answers from what it kept)
            var sf0 = document.getElementById('clSalesField'); if (sf0) { sf0.style.display = 'none'; }
            fill(ids.stepGroup, []);    // กลุ่มขั้นตอนขึ้นกับผลิตภัณฑ์ที่เลือก
            setStepGroupRequired(true); // ยังไม่เลือกผลิตภัณฑ์ = โชว์ * ไว้ก่อน (ปลดเมื่อรู้ผลว่าไม่บังคับ)
            optionSets().then(function (o) { return withNone(o && o.salesLines); })
                .then(function (list) {
                    fill(ids.product, list || [], true);
                    // มีผลิตภัณฑ์ตัวเดียว → เลือกให้อัตโนมัติ (ไม่ต้องให้ user เลือกเอง)
                    if (list && list.length === 1) { setSelect(ids.product, list[0].id); }
                });
            // พนักงานขาย/ผู้รับผิดชอบ — โชว์ให้เลือกได้แต่ไม่บังคับ (ว่าง = backend มอบหมายอัตโนมัติ)
            optionSets().then(function (o) { return (o && o.salePersons) || []; })
                .then(function (list) { fill(ids.sales, list || [], true); defaultSalesFromOwner(); });   // ★ 28/09 พนักงานขาย: แค่ชื่อ
            optionSets().then(function (o) { return o ? ownersOf(o) : null; })
                .then(function (list) {
                    ALL_OWNERS = list || [];
                    fill(ids.owner, ALL_OWNERS, true);   // ผู้รับผิดชอบ: โชว์แค่ชื่อ ไม่โชว์รหัส
                    // default ผู้รับผิดชอบเป็นตัวเอง — เฉพาะตอนเจอ id ตัวเองในลิสต์จริงเท่านั้น
                    // (ไม่เจอ = ไม่ auto-select อะไร ปล่อยว่างเหมือนเดิม)
                    if (!myEmployeeId) { return; }
                    var sel = document.getElementById(ids.owner);
                    if (!sel) { return; }
                    for (var i = 0; i < sel.options.length; i++) {
                        if (sel.options[i].value === myEmployeeId) { setSelect(ids.owner, myEmployeeId); break; }
                    }
                });
        }

        // เลือกผลิตภัณฑ์ → โหลดกลุ่มขั้นตอนของผลิตภัณฑ์นั้น
        // โหลด "ทุกผลิตภัณฑ์เสมอ" ห้ามข้ามตาม data-wf — backend รายงาน usesWorkflowStep ไม่ตรงกับข้อมูลจริงเสมอไป
        // (คอร์สผิวพรรณ/คอร์สลดความอ้วนมี group pipeline แต่ flag ไม่เป็น true) เชื่อ "ข้อมูลที่โหลดได้จริง" เป็นหลัก
        // บังคับเลือกเมื่อ: มีกลุ่มให้เลือกจริง หรือ ผลิตภัณฑ์นั้นมี WorkFlow Step
        function onProductChange() {
            var el = document.getElementById(ids.product);
            var mt = el ? el.value : '';
            if (mt === NO_LINE) { mt = ''; }
            var sf1 = document.getElementById('clSalesField'); if (sf1) { sf1.style.display = mt ? '' : 'none'; }
            fill(ids.stepGroup, []);
            setStepGroupRequired(true);   // ยังไม่รู้ผล API = ถือว่าบังคับไว้ก่อน กันเผลอข้าม
            onChange();
            if (!mt) { restoreOwners(); return; }
            loadOwnersOfLine(mt);
            var opt = el.options[el.selectedIndex];
            var wf = opt ? opt.getAttribute('data-wf') : null;
            env.fetch(env.ctx + '/board/master/activity-groups?movementTypeId=' + encodeURIComponent(mt), { credentials: 'same-origin' })
                .then(toJson).catch(function () { return null; })
                .then(function (d) {
                    var cur = document.getElementById(ids.product);
                    if (!cur || cur.value !== mt) { return; }   // เปลี่ยนผลิตภัณฑ์ระหว่างรอ → ทิ้งผลของตัวเก่า
                    var list = (d && d.result) || [];
                    fill(ids.stepGroup, list, true);
                    if (list.length) { var sg0 = document.getElementById(ids.stepGroup); if (sg0) { sg0.value = String(list[0].id); } }
                    setStepGroupRequired(list.length > 0 || wf === '1');
                    onChange();
                });
        }

        // เลือก "กลุ่มขั้นตอน" → refill "ผู้รับผิดชอบ" ให้เหลือเฉพาะคนในกลุ่มนั้นจริง (พนักงานขายไม่เกี่ยว แสดงทั้งหมดเสมอ)
        // ใช้ /master-data/employees/by-activity-group ซึ่งไม่ผูกกับ lead ต่างจาก /leads/{id}/forward-employees
        // ที่ต้องมี lead จริงเสมอ — ค่าที่เคยเลือกไว้ยังอยู่ในกลุ่มก็คงค่าเดิมไว้ ไม่งั้นล้างให้เลือกใหม่ /
        // ล้างกลุ่มกลับไป → คืนลิสต์เต็มทั้งบริษัท
        function onStepGroupChange() {
            var sgSel = document.getElementById(ids.stepGroup);
            var gid = sgSel ? sgSel.value : '';
            var prevOwner = (document.getElementById(ids.owner) || {}).value || '';
            if (!gid) {
                fill(ids.owner, ALL_OWNERS, true);
                // ค่าเดิมว่าง (โดนล้างตอนเลือกกลุ่มที่ไม่มีเรา) → default กลับเป็นตัวเอง
                var ownerBack = prevOwner || (ALL_OWNERS.some(function (e) { return String(e.id) === myEmployeeId; }) ? myEmployeeId : '');
                if (ownerBack) { setSelect(ids.owner, ownerBack); }
                return;
            }
            env.fetch(env.ctx + '/board/master/employees-by-activity-group?activityGroupId=' + encodeURIComponent(gid), { credentials: 'same-origin' })
                .then(toJson).catch(function () { return null; })
                .then(function (d) {
                    var curSg = document.getElementById(ids.stepGroup);
                    if (!curSg || curSg.value !== gid) { return; }   // เปลี่ยนกลุ่มระหว่างรอ → ทิ้งผลของกลุ่มเก่า
                    var groupList = (d && d.result) || [];
                    var groupIds = {};
                    groupList.forEach(function (e) { groupIds[String(e.id)] = true; });
                    fill(ids.owner, groupList, true);   // ผู้รับผิดชอบ: แสดงเฉพาะคนในกลุ่มนี้ (value = employee id ตรงๆ)
                    if (prevOwner && groupIds[prevOwner]) { setSelect(ids.owner, prevOwner); }
                    else if (myEmployeeId && groupIds[myEmployeeId]) { setSelect(ids.owner, myEmployeeId); }
                    // พนักงานขาย — ไม่กรองตามกลุ่มแล้ว แสดงทั้งหมดเสมอ ไม่แตะค่าที่เลือกไว้
                });
        }

        var ownerSel = document.getElementById(ids.owner);
        if (ownerSel) { ownerSel.addEventListener('change', defaultSalesFromOwner); }
        // ผู้รับผิดชอบ: ครอบด้วย dropdown กางลงล่างเสมอ (open_down_select.js)
        if (window.odsEnhance) { odsEnhance(ids.owner); }

        return {
            load: load,
            onProductChange: onProductChange,
            onStepGroupChange: onStepGroupChange,
            setSelect: setSelect,
            isStepGroupRequired: function () { return stepGroupRequired; }
        };
    }

    return { create: create };
}
